-- nvcx bridge: link NVC via "foreign" attribute to libnvcx.so. This RTL is
-- instantiated in the wrappers generated by nvcx.tcl - you should not use
-- this yourself.
entity bridge is
    generic (SNAPSHOT : string; GENERICS : string := "");
end entity;

architecture plugin of bridge is
    procedure nvcx_open(snapshot : string; name : string; generics : string) is
    begin
        report "nvcx: foreign binding not resolved (run nvc with --load libnvcx.so)"
	    severity failure;
    end procedure;

    attribute foreign of nvcx_open : procedure is "VHPI nvcx nvcx_open";
begin
    open_once : process
    begin
        nvcx_open(SNAPSHOT, bridge'path_name, GENERICS);
        wait;
    end process;
end architecture;
